function rememberOpenedOrder(orderId){lastOpenedOrderId=String(orderId);try{sessionStorage.setItem(LAST_OPENED_ORDER_KEY,lastOpenedOrderId)}catch{}root.querySelectorAll('.admin-kanban-card.is-last-opened').forEach(card=>card.classList.remove('is-last-opened'));root.querySelectorAll('[data-open-order]').forEach(button=>{if(String(button.dataset.openOrder)===lastOpenedOrderId)button.closest('.admin-kanban-card')?.classList.add('is-last-opened')})}
function orderHistoryMarkup(history,order){if(!history.length)return '';return `<section class="admin-order-history-wrap"><span class="admin-eyebrow">HISTORIAL</span><details class="admin-order-history-details"><summary>Ver detalle de actividad <span>${history.length} ${history.length===1?'evento':'eventos'}</span></summary><ul class="admin-order-history">${history.map(item=>`<li><div><strong>${safe(orderStatusLabel(item.status,order))}</strong>${item.note?`<small>${safe(item.note)}</small>`:''}</div><time datetime="${safe(item.created_at)}">${date(item.created_at)} · ${new Date(item.created_at).toLocaleTimeString('es-CL',{hour:'2-digit',minute:'2-digit'})}</time></li>`).join('')}</ul></details></section>`}
function orderDetailMarkup(order){const address=order.shipping_address||{},customer=orderCustomer(order),items=order.order_items||[],payments=order.payments||[],payment=payments.find(item=>item.provider==='mercado_pago')||payments.find(item=>item.provider==='transferencia_bancaria')||payments[0],paymentWarning=payment&&['rejected','cancelled'].includes(payment.status)?`<p class="admin-payment-transfer-notice">Mercado Pago ${paymentStatusLabel(payment.status).toLowerCase()}. No inicies producción: pide al cliente que reintente.</p>`:'',archived=Boolean(order.archived_at),next=archived?null:nextOrderStatus(order.status,order),phone=String(customer.phone||'').replace(/[^\d+]/g,''),wa=String(customer.phone||'').replace(/\D/g,''),history=[...(order.order_status_history||[])].sort((a,b)=>new Date(b.created_at)-new Date(a.created_at)),historyMarkup=orderHistoryMarkup(history,order),productsMarkup=`<div class="admin-order-products"><span class="admin-eyebrow">PRODUCTOS</span>${items.map(item=>`<div><span><strong>${safe(item.name_snapshot)}</strong><small>${safe(item.sku_snapshot||'Sin SKU')} · ${safe(item.print_sides)} · ${item.quantity} un.</small></span><b>${money(item.line_total_clp)}</b></div>`).join('')||'<p>Sin productos registrados.</p>'}<a class="admin-order-semitone" href="${DTF_SEMITONE_URL}" target="_blank" rel="noreferrer"><span><strong>Preparar semitonos DTF</strong><small>Abre el editor para procesar el arte de este pedido.</small></span><b aria-hidden="true">↗</b></a></div>`;return `<div class="dialog-title"><div><span class="admin-eyebrow">PEDIDO #${safe(order.id)} · ${order.source==='manual'?'MANUAL':'ONLINE'}${archived?' · ARCHIVADO':''}</span><h2>${safe(orderCustomerName(order))}</h2><small class="admin-order-created">Creado el ${dateTime(order.created_at)}</small></div><button type="button" class="dialog-close" aria-label="Cerrar">×</button></div>${adminOrderStepper(order)}${archived?'':`<div class="admin-order-contact"><a href="tel:${safe(phone)}">Llamar</a><a href="https://wa.me/${safe(wa)}" target="_blank" rel="noreferrer">WhatsApp</a><a href="mailto:${safe(customer.email||'')}">Email</a></div>`}<div class="admin-order-detail-grid"><section><span class="admin-eyebrow">CLIENTE Y ENTREGA</span><dl><div><dt>Nombre</dt><dd>${safe(orderCustomerName(order))}</dd></div><div><dt>Email</dt><dd>${safe(customer.email||'No informado')}</dd></div><div><dt>Teléfono</dt><dd>${safe(customer.phone||'No informado')}</dd></div><div><dt>${address.fulfillment==='pickup'?'Entrega':'Dirección'}</dt><dd>${safe(orderDestination(order))}</dd></div>${address.delivery_notes?`<div><dt>Entrega</dt><dd>${safe(address.delivery_notes)}</dd></div>`:''}${address.notes?`<div><dt>Notas</dt><dd>${safe(address.notes)}</dd></div>`:''}</dl>${historyMarkup}</section><section><span class="admin-eyebrow">COBRO</span>${productsMarkup}<dl><div><dt>Subtotal</dt><dd>${money(order.subtotal_clp)}</dd></div><div><dt>Despacho</dt><dd>${order.shipping_clp?money(order.shipping_clp):'Gratis'}</dd></div>${order.discount_clp?`<div><dt>Descuento ${safe(order.coupon_code||'')}</dt><dd>−${money(order.discount_clp)}</dd></div>`:''}<div><dt>Pago</dt><dd>${payment?`${safe(payment.provider)} · ${safe(paymentStatusLabel(payment.status))}`:'Sin registro de pago'}</dd></div><div class="admin-order-total"><dt>Total</dt><dd><strong>${money(order.total_clp)}</strong></dd></div></dl>${paymentWarning}</section></div><div class="dialog-actions admin-order-dialog-actions${archived?' is-archived':''}"><div class="admin-order-edit-blocker" hidden><strong>Cambios pendientes</strong><span>Revisa y aprueba o rechaza la edición para continuar.</span></div><div class="admin-order-action-group admin-order-tools"><span class="admin-order-action-label">Herramientas</span><div>${archived?`<button type="button" class="admin-secondary" data-restore-archived-order="${safe(order.id)}">Restaurar pedido</button>`:`${customer.email?`<button type="button" class="admin-secondary" data-resend-email="${safe(order.id)}">Reenviar email</button>`:''}<button type="button" class="admin-secondary" data-print-order="${safe(order.id)}">Imprimir etiqueta</button><button type="button" class="admin-secondary" data-archive-order="${safe(order.id)}">Archivar pedido</button>`}</div></div><div class="admin-order-action-group admin-order-progress-actions"><span class="admin-order-action-label">Siguiente paso</span><div>${next?`<button type="button" class="admin-primary" data-order-id="${safe(order.id)}" data-next-status="${safe(next.status)}"${order.edit_pending_approval?' disabled aria-disabled="true" title="Hay cambios pendientes de revisión"':''}>${safe(next.adminAction)}</button>`:'<span class="admin-order-complete">✓ Operación terminada</span>'}</div></div></div>`}
function manualItemMarkup(index){const productOptions=manualProductOptions.map(product=>`<option value="${product.id}">${product.label}</option>`).join('');const firstProduct=manualProductOptions[0];const sizeOptions=firstProduct.sizes.map(size=>`<option value="${size}">${size}</option>`).join('');const colorOptions=manualColorOptions.map(([color,label],colorIndex)=>`<label class="admin-manual-color" style="--sample-color:${color}"><input type="radio" name="item_color_${index}" value="${label}" ${colorIndex===0?'checked':''}><i aria-hidden="true"></i><span>${label}</span></label>`).join('');return `<article class="admin-manual-item" data-item-index="${index}"><div class="admin-manual-item-head"><strong>Producto ${index+1}</strong><button type="button" class="admin-danger-link" data-remove-item ${index===0?'hidden':''}>Quitar</button></div><div class="admin-form-grid"><label>Tipo de sustrato<select name="item_product_type">${productOptions}</select></label><label>Talla<select name="item_size">${sizeOptions}</select></label><fieldset class="admin-manual-colors admin-form-wide"><legend>Color del sustrato</legend><div>${colorOptions}</div></fieldset><label>Cantidad<input name="item_quantity" type="number" min="1" max="20" value="1" required></label><label>Precio unitario<input name="item_unit_price" type="number" min="0" step="10" required></label><label>Ubicación del estampado<select name="item_print_placement"><option value="front">Frente</option><option value="back">Espalda</option><option value="both">Frente y espalda</option><option value="none">Sin estampado</option></select></label><label>Detalle corto<input name="item_name" required placeholder="Ej. Nombre Emilia en arcoíris"></label><label class="admin-form-wide">Detalles del diseño<textarea name="item_design_details" rows="2" placeholder="Texto, colores, medidas, referencia o instrucciones para producción."></textarea></label></div></article>`}
function editOrderItemMarkup(item,index){return `<div class="admin-edit-order-item" data-edit-item-id="${safe(item.id||'')}" data-edit-item-index="${index}"><div class="admin-edit-order-item-head"><strong>Producto ${index+1}</strong>${item.id?`<button type="button" class="admin-danger-link" data-remove-edit-item>Quitar</button>`:''}</div><div class="admin-form-grid"><label>Detalle<input name="edit_item_name" value="${safe(item.name_snapshot||'')}" required></label><label>Cantidad<input name="edit_item_quantity" type="number" min="1" step="1" value="${item.quantity||1}" required></label><label>Precio unitario<input name="edit_item_price" type="number" min="0" step="1" value="${item.unit_price_clp||0}" required></label><label>Ubicación<select name="edit_item_print_sides"><option value="front" ${item.print_sides==='front'?'selected':''}>Frente</option><option value="back" ${item.print_sides==='back'?'selected':''}>Espalda</option><option value="both" ${item.print_sides==='both'?'selected':''}>Frente y espalda</option></select></label></div></div>`}
function editOrderDialogMarkup(order){const address=order.shipping_address||{},customer=orderCustomer(order),items=order.order_items||[];return `<dialog class="admin-dialog admin-edit-order-dialog" id="edit-order-dialog"><form id="edit-order-form"><div class="dialog-title"><div><span class="admin-eyebrow">PEDIDO #${safe(order.id)} · EDICIÓN</span><h2>Editar pedido</h2><p>Los cambios quedan pendientes hasta que los apruebes y envíes el email.</p></div><button type="button" class="dialog-close" aria-label="Cerrar">×</button></div><fieldset class="admin-form-section"><legend>Cliente</legend><div class="admin-form-grid"><label>Nombre<input name="first_name" value="${safe(customer.first_name||'')}" required></label><label>Apellido<input name="last_name" value="${safe(customer.last_name||'')}"></label><label>Email<input name="email" type="email" value="${safe(customer.email||'')}" required></label><label>Teléfono<input name="phone" type="tel" value="${safe(customer.phone||'')}" required></label></div></fieldset><fieldset class="admin-form-section"><legend>Entrega</legend><div class="admin-form-grid"><label>Modalidad<select name="fulfillment"><option value="pickup" ${address.fulfillment==='pickup'?'selected':''}>Retiro en tienda</option><option value="delivery" ${address.fulfillment!=='pickup'?'selected':''}>Despacho</option></select></label><label>Región<input name="region" value="${safe(address.region||'')}" placeholder="Región"></label><label>Comuna<input name="commune" value="${safe(address.commune||'')}"></label><label>Dirección<input name="address" value="${safe(address.address||'')}"></label><label>Depto. / casa / oficina<input name="address_extra" value="${safe(address.address_extra||'')}"></label><label class="admin-form-wide">Indicaciones<textarea name="delivery_notes" rows="2">${safe(address.delivery_notes||'')}</textarea></label></div></fieldset><fieldset class="admin-form-section"><legend>Productos</legend><div id="edit-order-items">${items.map(editOrderItemMarkup).join('')}</div><button type="button" class="admin-secondary admin-add-item" id="add-edit-order-item">+ Agregar producto</button></fieldset><fieldset class="admin-form-section"><legend>Notas internas</legend><label>Notas<textarea name="notes" rows="3">${safe(address.notes||'')}</textarea></label></fieldset><div class="dialog-actions"><button type="button" class="admin-secondary dialog-cancel">Cancelar</button><button type="submit" class="admin-primary">Guardar cambios</button></div><p class="admin-form-status" role="alert"></p></form></dialog>`}
function openOrderEditor(order){const existing=root.querySelector('#edit-order-dialog');existing?.remove();root.insertAdjacentHTML('beforeend',editOrderDialogMarkup(order));const dialog=root.querySelector('#edit-order-dialog'),form=dialog.querySelector('form'),items=dialog.querySelector('#edit-order-items');const wireItem=row=>row.querySelector('[data-remove-edit-item]')?.addEventListener('click',()=>{if(items.children.length>1)row.remove()});items.querySelectorAll('.admin-edit-order-item').forEach(wireItem);dialog.querySelector('#add-edit-order-item').onclick=()=>{const holder=document.createElement('div');holder.innerHTML=editOrderItemMarkup({},items.children.length);const row=holder.firstElementChild;items.append(row);wireItem(row)};dialog.querySelector('.dialog-close').onclick=()=>dialog.close();dialog.querySelector('.dialog-cancel').onclick=()=>dialog.close();form.onsubmit=event=>saveOrderEdit(event,order);dialog.addEventListener('close',()=>dialog.remove(),{once:true});dialog.showModal();dialog.querySelector('input')?.focus()}
async function saveOrderEdit(event,order){event.preventDefault();const form=event.currentTarget,button=event.submitter,status=form.querySelector('.admin-form-status'),rows=[...form.querySelectorAll('.admin-edit-order-item')];if(!rows.length){status.textContent='Agrega al menos un producto.';return}const items=rows.map(row=>({id:row.dataset.editItemId||null,name_snapshot:String(row.querySelector('[name="edit_item_name"]').value).trim(),quantity:Number(row.querySelector('[name="edit_item_quantity"]').value),unit_price_clp:Number(row.querySelector('[name="edit_item_price"]').value),print_sides:row.querySelector('[name="edit_item_print_sides"]').value,sku_snapshot:order.order_items.find(item=>String(item.id)===String(row.dataset.editItemId))?.sku_snapshot||'MANUAL-EDITADO'}));if(items.some(item=>!item.name_snapshot||item.quantity<1||item.unit_price_clp<0)){status.textContent='Revisa el nombre, cantidad y precio de cada producto.';return}button.disabled=true;button.textContent='Guardando…';const shippingAddress={...(order.shipping_address||{}),fulfillment:form.elements.fulfillment.value,region:String(form.elements.region.value).trim(),commune:String(form.elements.commune.value).trim(),address:String(form.elements.address.value).trim(),address_extra:String(form.elements.address_extra.value).trim(),delivery_notes:String(form.elements.delivery_notes.value).trim(),notes:String(form.elements.notes.value).trim(),customer:{first_name:String(form.elements.first_name.value).trim(),last_name:String(form.elements.last_name.value).trim(),email:String(form.elements.email.value).trim(),phone:String(form.elements.phone.value).trim()}},subtotal=items.reduce((sum,item)=>sum+item.quantity*item.unit_price_clp,0),total=subtotal+Number(order.shipping_clp||0)-Number(order.discount_clp||0),now=new Date().toISOString(),snapshot={shipping_address:order.shipping_address,items:order.order_items,subtotal_clp:order.subtotal_clp,shipping_clp:order.shipping_clp,discount_clp:order.discount_clp,total_clp:order.total_clp};const {error}=await supabase.from('orders').update({shipping_address:shippingAddress,subtotal_clp:subtotal,total_clp:total,edit_pending_approval:true,edit_pending_at:now,edit_pending_by:sessionUser?.id||null,edit_pending_snapshot:snapshot,updated_at:now}).eq('id',order.id);if(error){button.disabled=false;button.textContent='Guardar cambios';status.textContent=error.message;return}const keepIds=items.map(item=>item.id).filter(Boolean);const removed=order.order_items.filter(item=>item.id&&!keepIds.includes(String(item.id)));if(removed.length){const {error:removeError}=await supabase.from('order_items').delete().in('id',removed.map(item=>item.id));if(removeError){status.textContent=removeError.message;return}}for(const item of items){const payload={name_snapshot:item.name_snapshot,quantity:item.quantity,unit_price_clp:item.unit_price_clp,line_total_clp:item.quantity*item.unit_price_clp,print_sides:item.print_sides,sku_snapshot:item.sku_snapshot};const result=item.id?await supabase.from('order_items').update(payload).eq('id',item.id):await supabase.from('order_items').insert({...payload,order_id:order.id});if(result.error){status.textContent=result.error.message;return}}await supabase.from('order_status_history').insert({order_id:order.id,status:order.status,note:'Edición guardada por administración; pendiente de aprobación y envío al cliente.'});form.closest('dialog').close();await refreshData('Cambios guardados. Abre el pedido para comparar y aprobar la edición.')}
const editValue=value=>value===null||value===undefined||value===''?'—':safe(value)
function editAddressSummary(address={}){return [address.fulfillment==='pickup'?'Retiro en tienda':'Despacho',address.region,address.commune,address.address,address.address_extra].filter(Boolean).join(' · ')||'—'}
function editDiffRow(label,before,after,format=value=>editValue(value)){const changed=String(before??'')!==String(after??'');return `<div class="admin-edit-diff-row${changed?' is-changed':''}"><strong>${label}</strong><span>${format(before)}</span><span>${format(after)}</span></div>`}
function openEditApproval(order){const snapshot=order.edit_pending_snapshot||{},beforeCustomer=snapshot.shipping_address?.customer||{},afterCustomer=order.shipping_address?.customer||{},beforeItems=snapshot.items||[],afterItems=order.order_items||[];root.querySelector('#edit-approval-dialog')?.remove();const html=`<dialog class="admin-dialog admin-edit-approval-dialog" id="edit-approval-dialog"><div class="dialog-title"><div><span class="admin-eyebrow">PEDIDO #${safe(order.id)} · REVISIÓN</span><h2>Comparar cambios</h2><p>Revisa exactamente qué cambiará antes de enviar la actualización al cliente.</p></div><button type="button" class="ds-icon-button close-button dialog-close" aria-label="Cerrar"><span></span></button></div><div class="admin-edit-approval-body"><div class="admin-edit-diff-legend"><span></span><span>Antes</span><span>Después</span></div><section class="admin-edit-diff-section"><h3>Cliente</h3>${editDiffRow('Nombre',`${beforeCustomer.first_name||''} ${beforeCustomer.last_name||''}`.trim(),`${afterCustomer.first_name||''} ${afterCustomer.last_name||''}`.trim())}${editDiffRow('Email',beforeCustomer.email,afterCustomer.email)}${editDiffRow('Teléfono',beforeCustomer.phone,afterCustomer.phone)}</section><section class="admin-edit-diff-section"><h3>Entrega</h3>${editDiffRow('Destino',editAddressSummary(snapshot.shipping_address),editAddressSummary(order.shipping_address))}${editDiffRow('Indicaciones',snapshot.shipping_address?.delivery_notes,order.shipping_address?.delivery_notes)}${editDiffRow('Notas',snapshot.shipping_address?.notes,order.shipping_address?.notes)}</section><section class="admin-edit-diff-section"><h3>Productos</h3><div class="admin-edit-diff-products">${Math.max(beforeItems.length,afterItems.length)?Array.from({length:Math.max(beforeItems.length,afterItems.length)},(_,index)=>{const before=beforeItems[index]||{},after=afterItems[index]||{};return `<div class="admin-edit-diff-product"><strong>Producto ${index+1}</strong>${editDiffRow('Detalle',before.name_snapshot,after.name_snapshot)}${editDiffRow('Cantidad',before.quantity,after.quantity)}${editDiffRow('Precio unitario',before.unit_price_clp,after.unit_price_clp,money)}${editDiffRow('Total línea',before.line_total_clp,after.line_total_clp,money)}</div>`}).join(''):'<p>No hay productos para comparar.</p>'}</div></section><section class="admin-edit-diff-section admin-edit-diff-total"><h3>Resumen</h3>${editDiffRow('Subtotal',snapshot.subtotal_clp,order.subtotal_clp,money)}${editDiffRow('Despacho',snapshot.shipping_clp,order.shipping_clp,money)}${editDiffRow('Descuento',snapshot.discount_clp,order.discount_clp,money)}${editDiffRow('Total',snapshot.total_clp,order.total_clp,money)}</section></div><div class="dialog-actions admin-edit-approval-actions"><button type="button" class="admin-secondary" data-edit-again>Volver a editar</button><button type="button" class="admin-danger" data-reject-edit>Rechazar cambios</button><button type="button" class="admin-primary" data-approve-edit="${safe(order.id)}">Aprobar cambios</button></div></dialog>`;root.insertAdjacentHTML('beforeend',html);const dialog=root.querySelector('#edit-approval-dialog');dialog.querySelector('.dialog-close').onclick=()=>dialog.close();dialog.querySelector('[data-edit-again]').onclick=()=>{dialog.close();openOrderEditor(order)};dialog.querySelector('[data-reject-edit]').onclick=event=>rejectOrderEdit(event.currentTarget);dialog.querySelector('[data-approve-edit]').onclick=event=>approveOrderEdit(event.currentTarget);dialog.addEventListener('close',()=>dialog.remove(),{once:true});dialog.showModal()}
async function rejectOrderEdit(button){const order=adminData.orders.find(item=>String(item.id)===String(button.dataset.rejectEdit));if(!order)return;const snapshot=order.edit_pending_snapshot;if(!snapshot){toast('No encontramos la versión anterior para restaurar.');return}if(!window.confirm(`¿Rechazar y restaurar los cambios del pedido #${order.id}?`))return;button.disabled=true;button.textContent='Restaurando…';const {error:orderError}=await supabase.from('orders').update({shipping_address:snapshot.shipping_address,subtotal_clp:snapshot.subtotal_clp,shipping_clp:snapshot.shipping_clp,discount_clp:snapshot.discount_clp,total_clp:snapshot.total_clp,edit_pending_approval:false,edit_pending_at:null,edit_pending_by:null,edit_pending_snapshot:null,updated_at:new Date().toISOString()}).eq('id',order.id).eq('edit_pending_approval',true);if(orderError){button.disabled=false;button.textContent='Rechazar cambios';toast(orderError.message);return}const {error:deleteError}=await supabase.from('order_items').delete().eq('order_id',order.id);if(deleteError){toast(deleteError.message);return}const restored=(snapshot.items||[]).map(item=>({order_id:order.id,name_snapshot:item.name_snapshot,sku_snapshot:item.sku_snapshot,print_sides:item.print_sides,quantity:item.quantity,unit_price_clp:item.unit_price_clp,line_total_clp:item.line_total_clp}));if(restored.length){const {error:restoreError}=await supabase.from('order_items').insert(restored);if(restoreError){toast(restoreError.message);return}}await supabase.from('order_status_history').insert({order_id:order.id,status:order.status,note:'Edición rechazada por administración; se restauró la versión anterior.'});await refreshData('Cambios rechazados. Se restauró la versión anterior sin enviar email.')}
function emailRequestBody(order,kind,preview=false){const body={orderId:order.id,resend:true};if(kind==='payment'){body.resend=undefined;body.paymentEmail=true;body.paymentInstructions=order.payment_instructions}if(kind==='edit')body.orderEditEmail=true;if(preview)body.preview=true;return body}
async function sendOrderEmailAction(order,kind){const {data,error}=await supabase.functions.invoke('send-order-email',{body:emailRequestBody(order,kind)});if(error||data?.error){toast(data?.error||error?.message||'No pudimos enviar el email.');return false}await refreshData(kind==='edit'?(data.email?.sent?'Edición aprobada y email enviado al cliente.':'Edición aprobada; email pendiente de configuración.'):kind==='payment'?(data.email?.sent?'Datos de pago enviados y registrados.':'Email pendiente de configuración.'):data.email?.sent?'Email reenviado al cliente.':'Email pendiente de configuración.');return true}
async function openOrderEmailPreview(order,kind='resend'){const {data,error}=await supabase.functions.invoke('send-order-email',{body:emailRequestBody(order,kind,true)});if(error||data?.error){toast(data?.error||error?.message||'No pudimos cargar la vista previa.');return}root.querySelector('#order-email-preview-dialog')?.remove();const email=data.email||{},label=kind==='payment'?'Enviar datos de pago':kind==='edit'?'Aprobar y enviar email':'Reenviar email',dialog=document.createElement('dialog');dialog.id='order-email-preview-dialog';dialog.className='admin-dialog admin-email-preview-dialog';dialog.innerHTML=`<div class="dialog-title"><div><span class="admin-eyebrow">PEDIDO #${safe(order.id)} · EMAIL</span><h2>Vista previa del email</h2><p>Revisa la plantilla completa con los datos reales antes de enviarla.</p></div><button type="button" class="ds-icon-button close-button dialog-close" aria-label="Cerrar"><span></span></button></div><div class="admin-email-preview-meta"><div><span>Para</span><strong>${safe(data.recipient||orderCustomer(order).email||'Sin email')}</strong></div><div><span>Asunto</span><strong>${safe(email.subject||'')}</strong></div></div><iframe class="admin-email-preview-frame admin-email-preview-live-frame" title="Vista previa del email" sandbox=""></iframe><div class="dialog-actions admin-email-preview-actions"><button type="button" class="admin-secondary dialog-cancel">Volver</button><button type="button" class="admin-primary" data-confirm-email>${label}</button></div>`;root.append(dialog);const frame=dialog.querySelector('iframe');frame.srcdoc=email.html||'<p>No hay contenido disponible.</p>';const close=()=>{dialog.close();dialog.remove()};dialog.querySelector('.dialog-close').onclick=close;dialog.querySelector('.dialog-cancel').onclick=close;dialog.querySelector('[data-confirm-email]').onclick=async event=>{const button=event.currentTarget;button.disabled=true;button.textContent='Enviando…';const sent=await sendOrderEmailAction(order,kind);if(sent)close();else{button.disabled=false;button.textContent=label}};dialog.showModal()}
async function approveOrderEdit(button){const order=adminData.orders.find(item=>String(item.id)===String(button.dataset.editOrderApproval||button.dataset.editOrder||button.dataset.approveEdit));if(!order)return;await openOrderEmailPreview(order,'edit')}
function manualOrderDialog(){return `<dialog class="admin-dialog admin-manual-dialog" id="manual-order-dialog"><form id="manual-order-form"><div class="dialog-title"><div><span class="admin-eyebrow">VENTA PRESENCIAL · EN REVISIÓN</span><h2>Nuevo pedido manual</h2><p>Quedará en “Pedido ingresado” para revisarlo antes de tomarlo.</p></div><button type="button" class="dialog-close" aria-label="Cerrar">×</button></div><fieldset class="admin-form-section"><legend>1. Comprador</legend><div class="admin-form-grid"><label>Nombre<input name="first_name" required></label><label>Apellido<input name="last_name"></label><label>Email<input name="email" type="email" required></label><label>Teléfono<input name="phone" type="tel" required></label></div></fieldset><fieldset class="admin-form-section"><legend>2. Despacho o retiro</legend><div class="admin-form-grid"><label>Modalidad<select name="fulfillment"><option value="pickup">Retiro en tienda</option><option value="delivery">Despacho</option></select></label><label>Región${regionFilterHtml('manual-order-region')}</label><label>Comuna<input name="commune"></label><label>Dirección<input name="address"></label><label>Depto. / casa / oficina<input name="address_extra"></label><label class="admin-form-wide">Indicaciones de entrega<textarea name="delivery_notes" rows="2" placeholder="Referencia para encontrar la dirección o coordinar retiro."></textarea></label></div></fieldset><fieldset class="admin-form-section"><legend>3. Productos</legend><div id="manual-items">${manualItemMarkup(0)}</div><button type="button" class="admin-secondary admin-add-item" id="add-manual-item">+ Agregar producto</button></fieldset><fieldset class="admin-form-section"><legend>4. Datos de pago</legend><label class="admin-check"><input name="send_payment_email" type="checkbox" checked><span>Enviar datos de pago al crear el pedido</span></label><p class="admin-form-hint">Se registrará la fecha y la cuenta administradora cuando el proveedor confirme el envío.</p><div class="admin-payment-fields"><label class="admin-check"><input name="payment_transfer_enabled" type="checkbox" checked><span>Transferencia bancaria</span></label><div class="admin-form-grid"><label>Titular<input name="transfer_holder" placeholder="Nombre o razón social"></label><label>Banco<input name="transfer_bank"></label><label>Tipo de cuenta<input name="transfer_account_type" placeholder="Cuenta corriente"></label><label>Número de cuenta<input name="transfer_account_number"></label><label>RUT<input name="transfer_rut"></label><label>Email de transferencia<input name="transfer_email" type="email"></label></div><label class="admin-check"><input name="payment_mercado_pago_enabled" type="checkbox"><span>Link de pago Mercado Pago</span></label><label>Link de pago<input name="mercado_pago_url" type="url" placeholder="https://mpago.la/..."></label></div></fieldset><fieldset class="admin-form-section"><legend>5. Observaciones</legend><label>Notas del pedido<textarea name="notes" rows="3" placeholder="Acuerdos comerciales u otras notas internas."></textarea></label></fieldset><div class="dialog-actions"><button type="button" class="admin-secondary dialog-cancel">Cancelar</button><button type="submit" class="admin-primary">Ingresar a revisión</button></div><p class="admin-form-status" role="alert"></p></form></dialog>`}
function ordersView(){const orders=adminData.orders,overdueCount=orders.filter(order=>!order.archived_at&&isOrderOverdue(order)).length,columns=[['cart','En carrito',['cart','quote']],['incoming','Pedido ingresado',['incoming']],['processing','Preparando pedido',['processing']],['handoff','Listo para entrega / retiro',['handoff']],['completed','Pedido terminado',['completed']],['archived','Archivado',['archived']]];const action=`<button type="button" class="admin-primary" id="new-manual-order">${icon('plus')} Pedido manual</button>`;const board=columns.map(([stage,label,stages])=>{const stageOrders=stage==='archived'?orders.filter(order=>order.archived_at):orders.filter(order=>!order.archived_at&&stages.includes(orderKanbanStage(order)));return `<section class="admin-kanban-column${stage==='archived'?' is-archived-column':''}"><header><h2>${label}</h2><span>${stageOrders.length}</span></header><div>${stageOrders.map(orderCard).join('')||'<p class="admin-kanban-empty">No hay pedidos en esta etapa.</p>'}</div></section>`}).join('');const content=`${pageHeading('OPERACIÓN','Pedidos.','Vista resumida por etapa. Abre un pedido para contactar, revisar datos, avanzar o imprimir su etiqueta.',action)}<section class="admin-orders-toolbar"><strong>${orders.length} ${orders.length===1?'pedido':'pedidos'}</strong><span>${orders.filter(order=>order.source==='manual').length} manuales</span>${overdueCount?`<span class="admin-overdue-counter">⚠ ${overdueCount} ${overdueCount===1?'demorado':'demorados'}</span>`:''}</section><section class="admin-kanban">${board}</section><dialog class="admin-dialog admin-order-dialog" id="order-dialog"><div id="order-dialog-content"></div></dialog>${manualOrderDialog()}`;shell(content,'pedidos');wireOrders()}
async function openStatusChangePreview(order,button){const status=button.dataset.nextStatus,{data,error}=await supabase.functions.invoke('send-order-email',{body:{orderId:order.id,status,preview:true}});if(error||data?.error){console.error('No pudimos cargar la vista previa del email',error||data?.error);await advanceOrder(button,true);return}root.querySelector('#order-status-email-preview-dialog')?.remove();const email=data.email||{},dialog=document.createElement('dialog');dialog.id='order-status-email-preview-dialog';dialog.className='admin-dialog admin-email-preview-dialog';dialog.innerHTML=`<div class="dialog-title"><div><span class="admin-eyebrow">PEDIDO #${safe(order.id)} · EMAIL</span><h2>Vista previa del email</h2><p>Este mensaje se enviará al cliente al tomar el pedido.</p></div><button type="button" class="ds-icon-button close-button dialog-close" aria-label="Cerrar"><span></span></button></div><div class="admin-email-preview-meta"><div><span>Para</span><strong>${safe(data.recipient||orderCustomer(order).email||'Sin email')}</strong></div><div><span>Asunto</span><strong>${safe(email.subject||'')}</strong></div></div><iframe class="admin-email-preview-frame admin-email-preview-live-frame" title="Vista previa del email" sandbox></iframe><div class="dialog-actions admin-email-preview-actions"><button type="button" class="admin-secondary dialog-cancel">Volver</button><button type="button" class="admin-primary" data-confirm-status-email>Tomar pedido y enviar email</button></div>`;root.append(dialog);dialog.querySelector('iframe').srcdoc=email.html||'<p>No hay contenido disponible.</p>';const close=()=>{dialog.close();dialog.remove()};dialog.querySelector('.dialog-close').onclick=close;dialog.querySelector('.dialog-cancel').onclick=close;dialog.querySelector('[data-confirm-status-email]').onclick=async event=>{const confirmButton=event.currentTarget;confirmButton.disabled=true;confirmButton.textContent='Actualizando…';close();await advanceOrder(button,true)};dialog.showModal()}
async function advanceOrder(button,confirmed=false){const order=adminData.orders.find(item=>String(item.id)===button.dataset.orderId),status=button.dataset.nextStatus,label=orderStatusLabel(status);if(!order)return;if(order.edit_pending_approval){toast('No puedes avanzar: hay cambios pendientes de revisión.');lockPendingOrderActions();return}if(status==='in_production'&&!order.payment_confirmed_at){toast('Confirma primero que recibiste el pago antes de preparar el pedido.');installPaymentGate();return}if(!confirmed){await openStatusChangePreview(order,button);return}button.disabled=true;button.textContent='Actualizando…';if(import.meta.env.DEV&&String(order.id).startsWith('LOCAL-')){const orders=readLocalOrders(),local=orders.find(item=>item.id===order.id);if(local){const now=new Date().toISOString();local.status=status;local.order_status_history=[...(local.order_status_history||[]),{id:`${order.id}-${now}`,status,note:'Estado actualizado en el panel local.',created_at:now}];localStorage.setItem(LOCAL_DEMO_ORDERS_KEY,JSON.stringify(orders));await refreshData(`${label} · actualización local.`);return}}const {data,error}=await supabase.functions.invoke('update-order-status',{body:{orderId:order.id,status}});if(error||data?.error){button.disabled=false;button.textContent=nextOrderStatus(order.status,order)?.adminAction||'Reintentar';toast(data?.error||error?.message||'No pudimos actualizar el pedido.');return}await refreshData(data.email?.sent?`${label} · email enviado al cliente.`:`${label} · estado actualizado; email pendiente.`)}
