function paymentInstructionsDialogMarkup(order){const instructions=order.payment_instructions||{},transfer=instructions.transfer||{},hasTransfer=Boolean(instructions.transfer),hasMercado=Boolean(instructions.mercado_pago_url);return `<dialog class="admin-dialog admin-payment-dialog" id="payment-instructions-dialog"><form id="payment-instructions-form"><div class="dialog-title"><div><span class="admin-eyebrow">PEDIDO #${safe(order.id)} · COBRO</span><h2>Configurar datos de pago</h2><p>Estos datos se usarán en la plantilla de cobro que verá el cliente.</p></div><button type="button" class="dialog-close" aria-label="Cerrar">×</button></div><fieldset class="admin-form-section"><legend>Transferencia bancaria</legend><label class="admin-check"><input name="payment_transfer_enabled" type="checkbox" ${hasTransfer?'checked':''}><span>Incluir transferencia bancaria</span></label><div class="admin-payment-fields"><div class="admin-form-grid"><label>Titular<input name="transfer_holder" value="${safe(transfer.holder||'')}" placeholder="Nombre o razón social"></label><label>Banco<input name="transfer_bank" value="${safe(transfer.bank||'')}"></label><label>Tipo de cuenta<input name="transfer_account_type" value="${safe(transfer.account_type||'')}" placeholder="Cuenta corriente"></label><label>Número de cuenta<input name="transfer_account_number" value="${safe(transfer.account_number||'')}"></label><label>RUT<input name="transfer_rut" value="${safe(transfer.rut||'')}"></label><label>Email de transferencia<input name="transfer_email" type="email" value="${safe(transfer.email||'')}"></label></div></div></fieldset><fieldset class="admin-form-section"><legend>Mercado Pago</legend><label class="admin-check"><input name="payment_mercado_pago_enabled" type="checkbox" ${hasMercado?'checked':''}><span>Incluir link de pago Mercado Pago</span></label><label>Link de pago<input name="mercado_pago_url" type="url" value="${safe(instructions.mercado_pago_url||'')}" placeholder="https://mpago.la/..."></label></fieldset><div class="dialog-actions"><button type="button" class="admin-secondary dialog-cancel">Cancelar</button><button type="submit" class="admin-primary">Guardar datos de pago</button></div><p class="admin-form-status" role="alert"></p></form></dialog>`}
function openPaymentInstructionsEditor(order){root.querySelector('#payment-instructions-dialog')?.remove();root.insertAdjacentHTML('beforeend',paymentInstructionsDialogMarkup(order));const dialog=root.querySelector('#payment-instructions-dialog'),form=dialog.querySelector('form');dialog.querySelector('.dialog-close').onclick=()=>dialog.close();dialog.querySelector('.dialog-cancel').onclick=()=>dialog.close();form.onsubmit=async event=>{event.preventDefault();const button=event.submitter,status=form.querySelector('.admin-form-status'),transfer=form.elements.payment_transfer_enabled.checked?{holder:String(form.elements.transfer_holder.value||'').trim(),bank:String(form.elements.transfer_bank.value||'').trim(),account_type:String(form.elements.transfer_account_type.value||'').trim(),account_number:String(form.elements.transfer_account_number.value||'').trim(),rut:String(form.elements.transfer_rut.value||'').trim(),email:String(form.elements.transfer_email.value||'').trim()}:null,mercadoPago=form.elements.payment_mercado_pago_enabled.checked?String(form.elements.mercado_pago_url.value||'').trim():'';if(!transfer&&!mercadoPago){status.textContent='Incluye una transferencia o un link de Mercado Pago.';return}if(mercadoPago&&!/^https?:\/\//i.test(mercadoPago)){status.textContent='Ingresa un link válido de Mercado Pago.';return}button.disabled=true;button.textContent='Guardando…';const {error}=await supabase.from('orders').update({payment_instructions:{transfer,mercado_pago_url:mercadoPago||null},updated_at:new Date().toISOString()}).eq('id',order.id);if(error){button.disabled=false;button.textContent='Guardar datos de pago';status.textContent=error.message;return}dialog.close();await refreshData('Datos de pago guardados. Ahora puedes previsualizar y enviarlos.')};dialog.addEventListener('close',()=>dialog.remove(),{once:true});dialog.showModal();dialog.querySelector('input')?.focus()}
function unlockPaymentInstructions(order){root.querySelector('#payment-auth-dialog')?.remove();const dialog=document.createElement('dialog');dialog.id='payment-auth-dialog';dialog.className='admin-dialog admin-payment-auth-dialog';dialog.innerHTML=`<form><div class="dialog-title"><div><span class="admin-eyebrow">DATOS DE PAGO · SEGURIDAD</span><h2>Confirmar identidad</h2><p>Ingresa la contraseña de tu cuenta para editar los datos bancarios.</p></div><button type="button" class="dialog-close" aria-label="Cerrar">×</button></div><div class="admin-payment-auth-body"><label>Contraseña<input name="password" type="password" autocomplete="current-password" required></label><p class="admin-form-status" role="alert"></p></div><div class="dialog-actions"><button type="button" class="admin-secondary dialog-cancel">Cancelar</button><button type="submit" class="admin-primary">Continuar</button></div></form>`;root.append(dialog);const form=dialog.querySelector('form'),close=()=>{dialog.close();dialog.remove()};dialog.querySelector('.dialog-close').onclick=close;dialog.querySelector('.dialog-cancel').onclick=close;form.onsubmit=async event=>{event.preventDefault();const button=event.submitter,status=form.querySelector('.admin-form-status'),password=String(form.elements.password.value||'');button.disabled=true;button.textContent='Verificando…';const {data:{user}}=await supabase.auth.getUser();const {error}=await supabase.auth.signInWithPassword({email:user?.email||'',password});if(error){button.disabled=false;button.textContent='Continuar';status.textContent='La contraseña no es correcta.';form.elements.password.select();return}close();openPaymentInstructionsEditor(order)};dialog.addEventListener('close',()=>dialog.remove(),{once:true});dialog.showModal();dialog.querySelector('input')?.focus()}
