// Los originales permanecen privados: el enlace se firma únicamente al
// solicitar la descarga desde una sesión de administración autorizada.
root.addEventListener('click',async event=>{
 const trigger=event.target.closest('[data-open-order]');
 if(!trigger)return;
 const orderId=trigger.dataset.openOrder,content=root.querySelector('#order-dialog-content');
 if(!content||!/^\d+$/.test(orderId))return;
 content.dataset.artworkOrderId=orderId;
 const {data,error}=await supabase.from('order_items').select('id,name_snapshot,color_hex,quality_review,catalog_design_id,front_design_path,back_design_path').eq('order_id',orderId).order('id');
 if(error){toast('No pudimos cargar los archivos del pedido.');return}
 if(content.dataset.artworkOrderId!==orderId||!root.querySelector('#order-dialog')?.open)return;
 const products=content.querySelector('.admin-order-products'),customItems=(data||[]).filter(item=>!item.catalog_design_id);
 if(!products||!customItems.length)return;
 const section=document.createElement('section');section.className='admin-order-products';
 const heading=document.createElement('span');heading.className='admin-eyebrow';heading.textContent='ARCHIVOS ORIGINALES DEL CLIENTE';section.append(heading);
 for(const item of customItems){
  const row=document.createElement('div'),description=document.createElement('span'),name=document.createElement('strong'),details=document.createElement('small');
  name.textContent=item.name_snapshot;details.textContent=[item.color_hex&&`Color ${colorNameForHex(item.color_hex)}`,item.quality_review&&'Revisión de calidad'].filter(Boolean).join(' · ');
  description.append(name,details);row.append(description);
  for(const [side,path] of [['Frente',item.front_design_path],['Espalda',item.back_design_path]]){
   if(!path)continue;
   const button=document.createElement('button');button.type='button';button.className='admin-secondary';button.textContent=`Ver ${side.toLowerCase()}`;
   button.addEventListener('click',async()=>{
    const tab=window.open('about:blank','_blank');if(!tab){toast('Permite ventanas emergentes para descargar el diseño.');return}
    tab.opener=null;button.disabled=true;
    const {data:signed,error:signError}=await supabase.storage.from('customer-designs').createSignedUrl(path,60);
    button.disabled=false;
    if(signError||!signed?.signedUrl){tab.close();toast('No pudimos descargar el diseño.');return}
    tab.location.replace(signed.signedUrl);
   });row.append(button);
  }
  if(!item.front_design_path&&!item.back_design_path){const missing=document.createElement('small');missing.textContent='No hay archivo original asociado a este pedido.';row.append(missing)}
  section.append(row);
 }
 products.after(section);
});

function openQuoteEditor(order){
 root.querySelector('#quote-editor-dialog')?.remove();
 const dialog=document.createElement('dialog');dialog.id='quote-editor-dialog';dialog.className='admin-dialog';
 dialog.innerHTML=`<form><div class="dialog-title"><div><span class="admin-eyebrow">PEDIDO #${safe(order.id)} · COTIZACIÓN</span><h2>Responder cotización</h2><p>Guarda el detalle y valor de la propuesta para el cliente.</p></div><button type="button" class="dialog-close" aria-label="Cerrar">×</button></div><fieldset class="admin-form-section"><legend>Respuesta al cliente</legend><label>Detalle de la propuesta<textarea name="quote_message" rows="7" required placeholder="Ej. Incluye diseño de una tinta al frente, dos rondas de cambios y preparación para impresión.">${safe(order.quote_message||'')}</textarea></label><label>Valor total de la propuesta<input name="quoted_total_clp" type="number" min="0" step="1" required value="${Number(order.quoted_total_clp||order.total_clp||0)||''}"><small>Valor en pesos chilenos. El despacho se coordina aparte.</small></label></fieldset><div class="dialog-actions"><button type="button" class="admin-secondary dialog-cancel">Cancelar</button><button type="submit" class="admin-primary">Guardar cotización</button></div><p class="admin-form-status" role="alert"></p></form>`;
 root.append(dialog);const form=dialog.querySelector('form'),close=()=>{dialog.close();dialog.remove()};dialog.querySelector('.dialog-close').onclick=close;dialog.querySelector('.dialog-cancel').onclick=close;
 form.onsubmit=async event=>{event.preventDefault();const button=event.submitter,status=form.querySelector('.admin-form-status'),message=String(form.elements.quote_message.value||'').trim(),total=Math.round(Number(form.elements.quoted_total_clp.value));if(!message||!Number.isFinite(total)||total<0){status.textContent='Completa el detalle y un valor válido.';return}button.disabled=true;button.textContent='Guardando…';const now=new Date().toISOString();const {data:{user}}=await supabase.auth.getUser();const {error}=await supabase.from('orders').update({status:'quoted',quote_message:message,quoted_total_clp:total,quoted_at:now,quoted_by:user?.id||null,subtotal_clp:total,shipping_clp:0,discount_clp:0,total_clp:total,updated_at:now,price_snapshot:{...(order.price_snapshot||{}),quote_message:message,quoted_total_clp:total,quote_pending:false}}).eq('id',order.id).eq('request_type','creative');if(error){button.disabled=false;button.textContent='Guardar cotización';status.textContent=error.message;return}await supabase.from('order_status_history').insert({order_id:order.id,status:'quoted',note:`Cotización guardada por ${money(total)}.`});close();await refreshData('Cotización guardada. El pedido quedó listo para responder al cliente.')};
 dialog.showModal();form.elements.quote_message.focus();
}

root.addEventListener('click',event=>{const trigger=event.target.closest('[data-open-order]');if(!trigger)return;setTimeout(()=>{const order=adminData?.orders.find(item=>String(item.id)===String(trigger.dataset.openOrder));if(order?.request_type!=='creative')return;const content=root.querySelector('#order-dialog-content');if(!content||content.querySelector('[data-creative-request]'))return;const detail=content.querySelector('.admin-order-detail-grid>section');detail?.insertAdjacentHTML('afterbegin',`<section class="admin-creative-request" data-creative-request><span class="admin-eyebrow">IDEA DEL CLIENTE</span><p>${safe(order.request_details||'Sin detalle')}</p>${order.request_references?.length?`<small>Referencias: ${safe(order.request_references.map(item=>item.name).join(', '))}</small>`:''}${order.quote_message?`<div class="admin-quote-saved"><strong>Cotización guardada · ${money(order.quoted_total_clp)}</strong><p>${safe(order.quote_message)}</p></div>`:''}</section>`);const tools=content.querySelector('.admin-order-tools>div');if(tools&&!tools.querySelector('[data-quote-order]')){const quote=document.createElement('button');quote.type='button';quote.className='admin-primary';quote.dataset.quoteOrder=order.id;quote.textContent=order.status==='quoted'?'Editar cotización':'Responder con cotización';quote.onclick=()=>openQuoteEditor(order);tools.prepend(quote)}},0)},true);

function installManualChannelField(){const form=document.querySelector('#manual-order-form'),grid=form?.querySelector('.admin-form-section .admin-form-grid');if(!form||!grid||form.elements.channel)return;grid.insertAdjacentHTML('beforeend','<label>Canal de origen<select name="channel"><option value="whatsapp">WhatsApp</option><option value="web">Web</option><option value="instagram">Instagram</option><option value="other">Otro</option></select></label>')}
function manualChannelName(value){return {whatsapp:'WhatsApp',web:'Web',instagram:'Instagram',other:'Otro'}[value]||'Otro'}
document.addEventListener('click',event=>{if(event.target.closest('#new-manual-order'))installManualChannelField();if(event.target.closest('[data-open-order]'))setTimeout(()=>{const button=event.target.closest('[data-open-order]'),order=adminData.orders.find(item=>String(item.id)===String(button?.dataset.openOrder)),dl=document.querySelector('#order-dialog-content .admin-order-detail-grid section dl');if(order?.source==='manual'&&dl&&!dl.querySelector('[data-order-channel]'))dl.insertAdjacentHTML('afterbegin',`<div data-order-channel><dt>Canal</dt><dd>${safe(orderChannelLabel(order))}</dd></div>`)},0)},true)
document.addEventListener('submit',event=>{if(event.target?.id!=='manual-order-form')return;const form=event.target,channel=manualChannelName(form.elements.channel?.value),notes=String(form.elements.notes?.value||'').replace(/^Canal de origen:.*(?:\n\n|\n|$)/,'').trim();if(form.elements.notes)form.elements.notes.value=[`Canal de origen: ${channel}`,notes].filter(Boolean).join('\n\n')},true)

function colorNameForHex(value){const normalized=String(value||'').toLowerCase();return manualColorOptions.find(([hex])=>hex.toLowerCase()===normalized)?.[1]||'Color personalizado'}
function readableOrderItem(item){const variant=adminData.variants.find(candidate=>candidate.sku===item.sku_snapshot),modelRecord=Array.isArray(variant?.product_models)?variant.product_models[0]:variant?.product_models,parts=String(item.name_snapshot||'').split(' · '),model=modelRecord?.name||parts[0]||'Producto',size=variant?.size||parts[1]||'A definir',color=item.color_hex?colorNameForHex(item.color_hex):variant?.color_name||parts[2]||'A definir',design=variant?parts.slice(1).join(' · '):parts.slice(3).join(' · '),designLabel=design&&design!=='personalizada'?design:'Diseño cargado por cliente',placement={front:'Frente',back:'Espalda',both:'Frente y espalda'}[item.print_sides]||'Sin estampado';return {name:design&&design!=='personalizada'?`${model} · ${design}`:model,details:[`Talla ${size}`,`Color ${color}`,`Diseño: ${designLabel}`,placement].join(' · ')}}
document.addEventListener('click',event=>{if(!event.target.closest('[data-open-order]'))return;setTimeout(()=>{const button=event.target.closest('[data-open-order]'),order=adminData.orders.find(item=>String(item.id)===String(button?.dataset.openOrder)),rows=document.querySelectorAll('#order-dialog-content .admin-order-products>div');if(!order)return;(order.order_items||[]).forEach((item,index)=>{const row=rows[index];if(!row)return;const readable=readableOrderItem(item),name=row.querySelector('strong'),details=row.querySelector('small');if(name)name.textContent=readable.name;if(details)details.textContent=`${readable.details} · ${item.quantity} ${item.quantity===1?'unidad':'unidades'}`})},0)},true)
